// Nada foi tocado: nem estado, nem tentativas. Quem segura o lease termina o trabalho (ou o W90/W10 o devolve).
const j = $input.first().json;
return [{ json: { ok: false, continuar: false, controle: j.controle_pedido,
  motivo: j.existe ? `W20: lease ocupado por ${j.lease_antes}` : 'W20: licitação não existe',
  lease_tomado: false } }];

// O que o W20 fez, passo a passo, para execucoes_workflow.contadores e para o retorno.
const lease = $('Tomar lease').first().json;
const PASSOS = [['W21', 'Executar W21 Baixar'], ['W22', 'Executar W22 Ler'], ['W23', 'Executar W23 Extrair'],
                ['W24', 'Executar W24 Verificar e publicar']];
const passos = PASSOS.filter(([, no]) => $(no).isExecuted).map(([w, no]) => {
  const r = $(no).first().json || {};
  return { passo: w, ok: r.ok === true, estado: r.estado ?? null, motivo: r.motivo ?? null };
});
const ultimo = $input.first().json || {};
const w23 = $('Executar W23 Extrair').isExecuted ? ($('Executar W23 Extrair').first().json || {}) : {};
const w24 = $('Executar W24 Verificar e publicar').isExecuted ? ($('Executar W24 Verificar e publicar').first().json || {}) : {};
return [{ json: {
  controle: lease.controle, estado_inicial: lease.estado, execucao_workflow_id: lease.execucao_workflow_id,
  ok: true, adiado: ultimo.adiado === true,
  motivo: ultimo.motivo ?? (passos.length ? null : `nada a fazer no estado ${lease.estado}`),
  execucao_id: w23.execucao_id ?? null, verificacao_id: w24.verificacao_id ?? null, html_uri: w24.html_uri ?? null,
  passos,
} }];

const r = $('Resumo do sucesso').first().json;
const c = $input.first().json;
return [{ json: { ok: true, controle: r.controle, estado_inicial: r.estado_inicial, estado_final: c.estado_final,
  custo_brl: c.custo_brl == null ? null : Number(c.custo_brl), chamadas: Number(c.chamadas || 0),
  sem_preco: Number(c.sem_preco || 0), execucao_id: r.execucao_id, verificacao_id: r.verificacao_id,
  html_uri: r.html_uri, adiado: r.adiado, motivo: r.motivo, passos: r.passos,
  lease_devolvido: c.lease_devolvido === true, tentativas: c.tentativas,
  proxima_tentativa_em: c.proxima_tentativa_em, execucao_workflow_id: c.execucao_workflow_id } }];

// O que o W20 fez, passo a passo, para execucoes_workflow.contadores e para o retorno.
const lease = $('Tomar lease').first().json;
const PASSOS = [['W21', 'Executar W21 Baixar'], ['W22', 'Executar W22 Ler'], ['W23', 'Executar W23 Extrair'],
                ['W24', 'Executar W24 Verificar e publicar']];
const passos = PASSOS.filter(([, no]) => $(no).isExecuted).map(([w, no]) => {
  const r = $(no).first().json || {};
  return { passo: w, ok: r.ok === true, estado: r.estado ?? null, motivo: r.motivo ?? null };
});
const ultimo = $input.first().json || {};
const w23 = $('Executar W23 Extrair').isExecuted ? ($('Executar W23 Extrair').first().json || {}) : {};
const w24 = $('Executar W24 Verificar e publicar').isExecuted ? ($('Executar W24 Verificar e publicar').first().json || {}) : {};
return [{ json: {
  controle: lease.controle, estado_inicial: lease.estado, execucao_workflow_id: lease.execucao_workflow_id,
  ok: false, adiado: ultimo.adiado === true,
  motivo: ultimo.motivo ?? 'passo devolveu ok=false sem motivo',
  execucao_id: w23.execucao_id ?? null, verificacao_id: w24.verificacao_id ?? null, html_uri: w24.html_uri ?? null,
  passos,
} }];

const r = $('Resumo da falha').first().json;
const c = $input.first().json;
return [{ json: { ok: false, controle: r.controle, estado_inicial: r.estado_inicial, estado_final: c.estado_final,
  motivo: r.motivo, passos: r.passos, resultado: $('Registrar falha (fn_registrar_falha)').first().json.resultado ?? null,
  tentativas: c.tentativas, proxima_tentativa_em: c.proxima_tentativa_em,
  lease_devolvido: c.lease_por === null, execucao_workflow_id: c.execucao_workflow_id } }];
